/* @autogenerated */
import { Component } from '@angular/core';
import { fakeAsync, flush, TestBed } from '@angular/core/testing';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { concat, map, NEVER, of, throwError, timer } from 'rxjs';
import { TranslocoTestingModule } from '@jsverse/transloco';
import { EditableSelectoneComponent } from './editable-selectone.component';
import { selectorProvider } from '@shared/data/selector-provider';

describe('EditableSelectoneComponent', () => {
  afterEach(() => TestBed.resetTestingModule());

  function setup(search: () => any) {
    const provider = selectorProvider({
      search,
      select: () => of(undefined),
      equals: () => false,
      display: () => 'Item',
      value: () => ({ $ref: '1' }),
    });

    TestBed.configureTestingModule({
      imports: [
        EditableSelectoneComponent,
        TranslocoTestingModule.forRoot({
          langs: { en: { common: { selector: { open: 'Show options' } } } },
          translocoConfig: { availableLangs: ['en'], defaultLang: 'en' },
        }),
      ],
    });

    const fixture = TestBed.createComponent(EditableSelectoneComponent);
    fixture.componentRef.setInput('provider', provider);
    fixture.detectChanges();
    return { fixture, provider };
  }

  it('creates component with provider', () => {
    const { fixture } = setup(() => of([]));

    expect(fixture.componentInstance).toBeTruthy();
  });

  it('opens the options from a focusable button', fakeAsync(() => {
    const { fixture } = setup(() => of([]));
    const button: HTMLButtonElement = fixture.nativeElement.querySelector('button[matSuffix]');

    expect(button).toBeTruthy();
    expect(button.type).toBe('button');
    expect(button.getAttribute('aria-label')).toBe('Show options');

    const open = spyOn(fixture.componentInstance.autoTrigger()!, 'openPanel');
    button.click();
    flush();

    expect(open).toHaveBeenCalled();
  }));

  it('reports no results and errors', fakeAsync(() => {
    const empty = setup(() => of([]));
    // La selección inicial (diferida) limpia el provider: se espera antes de buscar
    flush();
    empty.provider.search('x');
    flush();
    expect(empty.fixture.componentInstance.noResults()).toBeTrue();
    expect(empty.fixture.componentInstance.feedbackErrorKey()).toBeNull();
    TestBed.resetTestingModule();

    const failing = setup(() => throwError(() => new Error('boom')));
    flush();
    failing.provider.search('x');
    flush();
    expect(failing.fixture.componentInstance.noResults()).toBeFalse();
    expect(failing.fixture.componentInstance.feedbackErrorKey()).toBe('common.selector.error');
  }));

  describe('with a slow search', () => {
    const wait = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

    @Component({
      imports: [EditableSelectoneComponent, ReactiveFormsModule],
      template: `<editable-selectone [formControl]="control" label="field" [provider]="provider" /><button
          id="outside"
        ></button>`,
    })
    class HostComponent {
      control = new FormControl(null);
      provider = selectorProvider<{ id: number }, number>({
        // Como los repositorios: emite y no completa
        search: () => concat(timer(100).pipe(map(() => [{ id: 1 }, { id: 2 }])), NEVER),
        select: (id) => of({ id }),
        equals: (one, other) => one === other,
        display: (item) => `Item ${item.id}`,
        value: (item) => item.id,
      });
    }

    async function open() {
      TestBed.configureTestingModule({
        imports: [
          HostComponent,
          TranslocoTestingModule.forRoot({
            langs: { en: {} },
            translocoConfig: { availableLangs: ['en'], defaultLang: 'en' },
          }),
        ],
      });
      const fixture = TestBed.createComponent(HostComponent);
      document.body.appendChild(fixture.nativeElement);
      fixture.autoDetectChanges();
      await wait(50);
      const editable = fixture.debugElement.children[0].componentInstance as EditableSelectoneComponent<
        unknown,
        number
      >;
      const button: HTMLButtonElement = fixture.nativeElement.querySelector('button[matSuffix]');
      button.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true }));
      button.click();
      return { fixture, editable, provider: fixture.componentInstance.provider };
    }

    function cancel(fixture: { nativeElement: HTMLElement }) {
      (fixture.nativeElement.querySelector('#outside') as HTMLButtonElement).focus();
      document.body.click();
    }

    afterEach(() => document.querySelectorAll('[ng-version], editable-selectone').forEach((node) => node.remove()));

    it('opens the panel with the first click', async () => {
      const { fixture, editable, provider } = await open();
      await wait(250);

      expect(provider()?.length).toBe(2);
      expect(editable.autoTrigger()!.panelOpen).toBeTrue();
      expect(provider.searching()).toBeFalse();
      fixture.destroy();
    });

    it('stops the progress when cancelled during the search', async () => {
      const { fixture, provider } = await open();
      await wait(20);
      cancel(fixture);
      await wait(250);

      expect(provider.searching()).toBeFalse();
      fixture.destroy();
    });
  });
});
